// WF1 — Code node "Route" (Run Once for All Items). Replaces the current Route.
// Changes vs. before:
//  1. /new and /HR (/rh) are dialog commands, like /nouveau.
//  2. The FULL text is passed for dialog commands, so "/new" + pasted lines in one message works
//     (before, only the first word was kept and the rest was lost).
//  3. Plain dialog messages that arrive in the same poll from the same chat are merged into one
//     item. Otherwise all of them read the same old session state and only the last one counts.

const updates = $('Get updates').first().json.result || [];
const apps = $('Applicants').all().map(i => i.json);
const DIALOG_CMD = /^\/(nouveau|new|annuler|start|hr|rh)(@\w+)?$/i;
const out = [];

for (const u of updates) {
  const chatId = u.message?.chat?.id ?? u.callback_query?.message?.chat?.id;
  const app = apps.find(a => String(a.chat_id) === String(chatId));
  if (!app) continue;                                   // whitelist
  const base = { applicant_id: app.id, chat_id: chatId };
  if (u.callback_query) {
    const d = String(u.callback_query.data || '');
    if (d.startsWith('dlg:')) out.push({ ...base, type: 'dialog', text: d.slice(4), callback_id: u.callback_query.id });
    else out.push({ ...base, type: 'callback', data: d, callback_id: u.callback_query.id });
  } else if (u.message?.document) {
    out.push({ ...base, type: 'document', file_id: u.message.document.file_id });
  } else if (u.message?.text) {
    const text = u.message.text.trim();
    const word = text.split(/\s+/)[0];
    if (DIALOG_CMD.test(word)) out.push({ ...base, type: 'dialog', text });          // keep pasted lines
    else if (text.startsWith('/')) out.push({ ...base, type: 'command', text });
    else if (text.includes(';')) out.push({ ...base, type: 'text', text });          // bulk lines
    else out.push({ ...base, type: 'dialog', text });                                // answer in the dialog
  }
}

// Merge consecutive typed dialog messages of the same chat (not button presses).
// A new /nouveau, /new, /annuler or /start always starts a fresh item.
const startsFresh = t => /^\/(nouveau|new|annuler|start)\b/i.test(t);
const merged = [];
for (const it of out) {
  const prev = merged[merged.length - 1];
  const typed = j => j && j.type === 'dialog' && !j.callback_id;
  if (typed(it) && typed(prev) && prev.chat_id === it.chat_id
      && !startsFresh(it.text) && !/^\/(annuler|start)\b/i.test(prev.text)) {
    prev.text += '\n' + it.text;
  } else merged.push({ ...it });
}
return merged.map(json => ({ json }));

const cb = $('Parse callback').item.json;
const row = $('Apply decision').item.json;
let msg;
if (!row.company) msg = '⚠️ Déjà traité ou introuvable.';
else if (cb.action === 'approve') msg = `✅ Validé : ${row.company} — envoi programmé.`;
else if (cb.action === 'skip') msg = `❌ Ignoré : ${row.company}.`;
else msg = `🔄 Nouvelle version en préparation : ${row.company}.`;
return { json: { chat_id: cb.chat_id, msg } };

// Bulk format: Entreprise; email entreprise; adresse; code postal et localité; nom RH; email RH
const re = /^[^\s@;]+@[^\s@;]+\.[a-z]{2,}$/i;
const b = s => Buffer.from(' ' + String(s || ''), 'utf8').toString('base64'); // leading space: never empty
const out = [], bad = [];
let chat_id, applicant_id;
for (const it of $input.all()) {
  chat_id = it.json.chat_id; applicant_id = it.json.applicant_id;
  for (const raw of String(it.json.text || '').split(/\r?\n/)) {
    const l = raw.trim(); if (!l) continue;
    const [company = '', email = '', address = '', postcity = '', hr_name = '', hr_email = ''] = l.split(';').map(s => s.trim());
    const e = email.toLowerCase(), h = hr_email.toLowerCase();
    if (!company || !re.test(e) || (h && !re.test(h))) { bad.push(l); continue; }
    out.push({ json: { applicant_id, chat_id, company, email: e, email_domain: e.split('@')[1],
      company_b64: b(company), address_b64: b(address), postcity_b64: b(postcity),
      contact_b64: b(hr_name), hr_email_b64: b(h) } });
  }
}
if (!out.length) return [{ json: { chat_id, nothing: true, _invalid: bad } }];
out.forEach(o => o.json._invalid = bad);
return out;

const parsed = $('Parse lines').all();
const added = $('Insert target').all().filter(i => i.json.id).length;
const dups = parsed.length - added;
const bad = parsed[0].json._invalid || [];
let msg = `✅ ${added} entreprise(s) ajoutée(s)`;
if (dups) msg += `\n⚠️ ${dups} doublon(s) ignoré(s)`;
if (bad.length) msg += `\n❌ Format invalide :\n` + bad.join('\n');
return [{ json: { chat_id: parsed[0].json.chat_id, msg } }];

const cmd = $('By type').first().json;
const word = String(cmd.text || '').split(/\s+/)[0].toLowerCase();
let msg;
if (word === '/stats') {
  const rows = $('Stats').all().map(i => i.json).filter(r => r.status);
  const labels = { new: 'nouvelles', checking: 'vérification', email_found: 'à rédiger', no_email: 'domaine invalide',
    drafting: 'en rédaction', awaiting_approval: 'à valider', queued: 'en file d\'envoi', sending: 'envoi en cours',
    sent: 'envoyées', replied: 'réponses', skipped: 'ignorées', stop: 'stoppées', error: 'erreurs' };
  msg = rows.length
    ? '📊 Statistiques :\n' + rows.map(r => `• ${labels[r.status] || r.status} : ${r.n}`).join('\n')
    : '📊 Aucune entreprise enregistrée pour le moment.';
} else {
  msg = 'ℹ️ Pour ajouter une entreprise : /nouveau (le bot pose les questions).\n\nOu plusieurs d\'un coup, une ligne par entreprise :\nEntreprise; email entreprise; adresse; code postal et localité; nom RH; email RH\n\nAutres commandes : /stats, /annuler';
}
return [{ json: { chat_id: cmd.chat_id, msg } }];

// WF1 — Code node "Dialog" (Run Once for Each Item). Drop-in replacement:
// same inputs ($('By type').item.json + Load session row) and same output fields as before.
// Difference: every answer is classified, so she can type or paste fields in any order,
// one per message or all in one block. The bot then only asks for what is still missing.

const src = $('By type').item.json;
const raw = String(src.text || '').trim();
const step = $json.step || 'done';
let data = {}; try { data = typeof $json.data === 'string' ? JSON.parse($json.data) : ($json.data || {}); } catch (e) {}

// ---------- UI ----------
const btn = (t, d) => ({ text: t, callback_data: 'dlg:' + d });
const kb = rows => ({ inline_keyboard: rows });
const NEW = kb([[btn('➕ Nouvelle entreprise', 'new')]]);
const CANCEL = kb([[btn('❌ Annuler', 'cancel')]]);
const SKIP = kb([[btn('⏭️ Passer', 'skip')], [btn('❌ Annuler', 'cancel')]]);
const ask = {
  company:       ["🏢 Nom de l'entreprise ?\n\n(Tu peux aussi tout coller d'un coup : nom, email, adresse, RH… dans n'importe quel ordre.)", CANCEL],
  company_email: ["📧 Email de l'entreprise ?", CANCEL],
  address:       ['📍 Adresse (rue et numéro) ?', SKIP],
  postcity:      ['📮 Code postal et localité ? (ex : L-9054 Ettelbruck)', SKIP],
  has_hr:        ["👤 As-tu le nom et l'email du responsable RH ?", kb([[btn('Oui', 'yes'), btn('Non', 'no')], [btn('❌ Annuler', 'cancel')]])],
  hr_name:       ['👤 Nom du responsable RH ? (ex : Madame Weber)', SKIP],
  hr_email:      ['📧 Email du responsable RH ?', SKIP],
};
const LABEL = { company: 'entreprise', email: 'email entreprise', address: 'adresse', postcity: 'code postal',
                hr_name: 'contact RH', hr_email: 'email RH' };
const STEP_FIELD = { company: 'company', company_email: 'email', address: 'address', postcity: 'postcity',
                     hr_name: 'hr_name', hr_email: 'hr_email' };
const HR_STEPS = ['has_hr', 'hr_name', 'hr_email'];

// ---------- classifier ----------
const EMAIL_G  = /[^\s@;,<>()"']+@[^\s@;,<>()"']+\.[a-z]{2,}/gi;
const PHONE    = /^(t[ée]l\.?|tel:|phone:?)?\s*\+?[\d\s().\/-]{8,}$/i;
const PERSON   = /^(monsieur|madame|mademoiselle|m\.|mme\.?|mlle\.?|mr\.?|mrs\.?|ms\.?|herr|frau)\s+\S/iu;
const POSTAL   = /^(?:[A-Z]{1,2}\s?-\s?)?\d{4,5}\s+\p{L}/iu;                 // L-9012 Ettelbruck, 4000 Liège
const STREET   = /(?<!\p{L})(rue|avenue|av\.|boulevard|bd|route|rte|place|chemin|all[ée]e|impasse|quai|square|cit[ée]|zone|parc|rond-point|op|um|an der|strooss|stra(?:ss|ß)e|str\.|weg|b\.?p\.?|bo[iî]te postale)(?!\p{L})/iu;
const NUM_LEAD = /^\d+(\s*[-\/]\s*\d+)?\s*,?\s+\p{L}/u;                     // "12 Bonnevoie" yes, "3D Print" no
const NUM_ONLY = /^\d+(\s*[-\/]\s*\d+)?[a-z]?$/i;
const COUNTRY  = /^(luxembourg|lëtzebuerg|grand-duché de luxembourg|belgique|belgium|france|deutschland|allemagne|germany)$/i;
const HR_CMD   = /^\/(hr|rh)(@\w+)?(?=\s|$)/i;
const NEW_CMD  = /^\/(nouveau|new)(@\w+)?(?=\s|$)/i;
const clean = s => String(s).replace(/\s+/g, ' ').trim();

// "24-40 Av. des Alliés, 9012 Ettelbruck, Luxembourg" -> street + postal (country dropped).
// Only splits when a later segment is a postcode, so "24-40, Avenue des Alliés" stays whole.
const splitAddr = l => {
  const parts = l.split(/\s*,\s*/);
  if (!parts.slice(1).some(p => POSTAL.test(p))) return [l];
  const out = [];
  for (const p of parts) {
    if (out.length && NUM_ONLY.test(out[out.length - 1])) out[out.length - 1] += ', ' + p;
    else out.push(p);
  }
  return out.filter(p => !COUNTRY.test(p));
};
const kind = l =>
  PHONE.test(l)  ? 'phone'  :
  PERSON.test(l) ? 'person' :
  POSTAL.test(l) ? 'postal' :
  (STREET.test(l) && /\d/.test(l)) ? 'street' :
  NUM_LEAD.test(l) ? 'maybe_street' : 'other';

// Apply text to data. stepField = the field the bot just asked for (single-line answer),
// or null for a pasted block. Returns { noted: [fields set], ignored: [lines], badEmail }.
function apply(text, section, stepField) {
  const lines = String(text).split(/\r?\n/).map(clean).filter(Boolean);
  const block = lines.length > 1 || stepField === null;
  const noted = new Set(), ignored = [];
  let badEmail = false, tookCompany = false, tookHrName = false;
  const set = (k, v) => { data[k] = v; noted.add(k); };

  for (let l of lines) {
    if (HR_CMD.test(l)) { section = 'hr'; l = clean(l.replace(HR_CMD, '')); if (!l) continue; }
    if (NEW_CMD.test(l)) { l = clean(l.replace(NEW_CMD, '')); if (!l) continue; }

    // e-mails anywhere in the line ("Monsieur X x@y.lu" works)
    for (const e of (l.match(EMAIL_G) || [])) {
      const m = e.toLowerCase();
      if (section === 'hr' || stepField === 'hr_email') set('hr_email', m);
      else if (!data.email || stepField === 'email') set('email', m);
      else set('hr_email', m);                         // 2nd company-section email: it gets the mail too
    }
    l = clean(l.replace(EMAIL_G, ''));
    if (!l) continue;

    for (const p of splitAddr(l)) {
      const k = kind(p);
      if (k === 'phone') { ignored.push(p); continue; }   // never goes into the letter
      if (k === 'person') { set('hr_name', p); continue; }
      if (k === 'postal') { set('postcity', p); continue; }
      if (k === 'street') { set('address', p); continue; }
      if (k === 'maybe_street' && (stepField === 'address' || (block && data.address === undefined))) { set('address', p); continue; }

      // free text: the answer to what was asked, or the first free line of a block
      if (!block && stepField) {
        if (stepField === 'email' || stepField === 'hr_email') badEmail = true;
        else set(stepField, p);
      } else if (section === 'hr' && !tookHrName) { set('hr_name', p); tookHrName = true; }
      else if (section !== 'hr' && !tookCompany)  { set('company', p); tookCompany = true; }
      else ignored.push(p);
    }
  }
  return { noted: [...noted], ignored, badEmail };
}

// First field still missing. undefined = never answered, '' = skipped on purpose.
const nextStep = d =>
  !d.company ? 'company' :
  !d.email ? 'company_email' :
  d.address === undefined ? 'address' :
  d.postcity === undefined ? 'postcity' :
  (d.hr_name === undefined && d.hr_email === undefined) ? 'has_hr' :
  d.hr_name === undefined ? 'hr_name' :
  d.hr_email === undefined ? 'hr_email' : 'confirm';

// ---------- state machine ----------
let next = step, msg = '', markup = null, finish = false, prefix = '';
const go = s => { next = s; if (ask[s]) [msg, markup] = ask[s]; };
const goNext = () => go(nextStep(data));
const report = r => {
  const extra = r.noted.filter(k => k !== STEP_FIELD[step]);           // say so when it landed elsewhere
  if (r.noted.length > 1 || extra.length) prefix += `✔️ Noté : ${r.noted.map(k => LABEL[k]).join(', ')}\n`;
  if (r.ignored.length) prefix += `(ignoré : ${r.ignored.join(' · ')})\n`;
  if (r.badEmail) prefix += '⚠️ Email invalide.\n';
  if (prefix) prefix += '\n';
};
const isSkip = raw === 'skip' || raw === '-';
const section = HR_STEPS.includes(step) ? 'hr' : 'company';

if (/^\/annuler\b/i.test(raw) || raw === 'cancel') { next = 'done'; data = {}; msg = '❌ Saisie annulée.'; markup = NEW; }
else if (NEW_CMD.test(raw) || raw === 'new') {
  data = {};
  const rest = raw === 'new' ? '' : raw.replace(NEW_CMD, '').trim();
  if (rest) report(apply(rest, 'company', null));
  goNext();
}
else if (HR_CMD.test(raw) && step !== 'done') {
  const rest = raw.replace(HR_CMD, '').trim();
  if (rest) { report(apply(rest, 'hr', null)); goNext(); }
  else go('hr_name');
}
else if (/^\/start\b/i.test(raw)) { next = 'done'; msg = '👋 Pour ajouter une entreprise, appuie sur le bouton (ou envoie /nouveau).'; markup = NEW; }
else if (step === 'done') {
  // Pasted a block without /nouveau: start automatically if it clearly contains company data.
  const probe = { ...data }; data = {};
  const r = apply(raw, 'company', null);
  if (data.email && Object.keys(data).length >= 2) { report(r); goNext(); }
  else { data = probe; next = 'done'; msg = '👋 Pour ajouter une entreprise, appuie sur le bouton (ou envoie /nouveau).'; markup = NEW; }
}
else if (step === 'confirm') {
  if (raw === 'save' || /^(oui|ok|yes)$/i.test(raw)) { finish = true; next = 'done'; }
  else { report(apply(raw, 'company', null)); goNext(); }             // typed a correction at the recap
}
else if (step === 'has_hr') {
  if (raw === 'yes' || /^oui$/i.test(raw)) go('hr_name');
  else if (raw === 'no' || /^non$/i.test(raw)) { data.hr_name = ''; data.hr_email = ''; goNext(); }
  else { report(apply(raw, 'hr', null)); goNext(); }                   // typed/pasted the contact directly
}
else if (STEP_FIELD[step]) {
  const field = STEP_FIELD[step];
  if (isSkip) {
    if (['address', 'postcity', 'hr_name', 'hr_email'].includes(field)) data[field] = '';
    goNext();
  } else if (['yes', 'no', 'save'].includes(raw)) {
    go(step);                                                          // stale button press
  } else {
    const r = apply(raw, section, field);
    report(r);
    if (r.badEmail && !r.noted.includes(field)) go(step); else goNext();
  }
}
else { next = 'done'; msg = '👋 Envoie /nouveau pour ajouter une entreprise.'; markup = NEW; }

if (next === 'confirm') {
  const att = data.hr_name ? `À l'attention de ${data.hr_name}` : "À l'attention du service Ressources humaines";
  const to = [data.email, data.hr_email].filter(Boolean).join('\n   + ');
  const addr = [data.address, data.postcity].filter(Boolean).join(', ') || "(pas d'adresse)";
  msg = `📋 Récapitulatif\n\n🏢 ${data.company}\n${att}\n📍 ${addr}\n📧 Envoi à : ${to}\n\nEnregistrer ?\n(Pour corriger, envoie simplement la bonne info.)`;
  markup = kb([[btn('✅ Enregistrer', 'save'), btn('❌ Annuler', 'cancel')]]);
}
msg = prefix + msg;

// ---------- output (unchanged shape) ----------
const b = s => Buffer.from(' ' + String(s || ''), 'utf8').toString('base64'); // leading space: never empty
const tg_body = { chat_id: src.chat_id, text: msg };
if (markup) tg_body.reply_markup = markup;
const email = data.email || '';
return { json: { chat_id: src.chat_id, applicant_id: src.applicant_id, finish, step: next,
  data_b64: Buffer.from(JSON.stringify(data), 'utf8').toString('base64'), tg_body,
  company: data.company || '', email, email_domain: email.split('@')[1] || '',
  company_b64: b(data.company), address_b64: b(data.address), postcity_b64: b(data.postcity),
  contact_b64: b(data.hr_name), hr_email_b64: b(data.hr_email) } };

const d = $('Dialog').item.json;
const ok = !!$json.id;
const msg = ok
  ? `✅ ${d.company} enregistrée. La lettre arrive dans quelques minutes.\n\nPour une autre entreprise : /nouveau`
  : `⚠️ ${d.company} existe déjà (même nom ou même domaine email).\n\nPour une autre entreprise : /nouveau`;
return { json: { chat_id: d.chat_id, msg } };
